\begin{align}\label{1.1}
\min_{x\in\mathbb{R}^p} f(x):= \frac{1}{n} \sum_{i=1}^nf_i(x) ,
\end{align}

Here $f_i:\mathbb{R}^p\rightarrow\mathbb{R}$ is a local objective function (or cost function of agent $i$) and $n$ is the number of agents.


where $F$ denotes the aggregate cost function in (\ref{1.1}):
\[
F({\bf x}) =\sum_{i=1}^nf_i(x_i).
\]

Here $I_p$ is the $p\times p$ identity matrix, ${\bf x}$ denotes an $np$ dimensional column vector made by stacking up $x_i\in\mathbb{R}^p$ $(i=1,\cdots,n)$:



$${\bf x}= (x_{1}^{\top}, x_{2}^{\top}, \cdots, x_{n}^{\top})^{\top},$$

  and the consensus matrix $W$ is the  $n\times n$ matrix that contains the information on the connectivity of the underlying network:
\begin{equation}\label{stack}
%{\bf x}=\begin{pmatrix} x_1 \\  \vdots \\ x_n\end{pmatrix},\quad 
W= \begin{pmatrix} w_{11} & w_{12} & \cdots & w_{1n} \\ w_{21} & w_{22} & \cdots &w_{2n} \\ \vdots &\vdots &\ddots &\vdots \\ w_{n1} & w_{n2} &\cdots &w_{nn}
\end{pmatrix}. 
\end{equation}

Throughout this paper, we assume the following properties for the consensus matrix:%\newline
%{\bf Assumptions on the consensus matrix }$W$:
%We assume the consensus matrix
{\color{black}
\begin{itemize}
\item $W$ is a doubly-stochastic $n\times n$ matrix.
\item The directed graph associated to $W$ is strongly connected, and has a self-loop at every vertex.
\end{itemize}


In Lemma \ref{newlemma}, we will show that the graph associated to $W^\top W$ is connected, and so the eigenvalue $1$ of $W^\top W$ is simple and all other eigenvalues have modulus strictly less than 1. We let $\beta\in[0,1)$ be the square root of the second largest eigenvalue of $W^\top W$, which is equal to the spectral norm of $W-\frac{1}{n}1_n1_n^\top$, where $1_n$ is a column vector in $\mathbb{R}^n$ whose entries are all $1$.} We let $f^*$ be the optimal objective value of \eqref{1.1} and denote by ${X}^*$ the set of optimal solutions to \eqref{1.1} which is assumed to be nonempty, i.e., 
\begin{equation*}
{X}^* = \{x \in \mathbb{R}^p ~:~ f(x) =f^*\}.
\end{equation*}

\noindent {\bf Notation.} $\|\cdot\|$ denotes the standard $\ell^2$-norm in the Euclidean space, or the operator norm induced by the $\ell^2$-norm, depending on the context.


\begin{defn}For given $\alpha \geq 0$, a function $\mathbf{f}: \mathbb{R}^p \rightarrow \mathbb{R}$ is called $\alpha$-strongly convex (convex if $\alpha =0$) if
\begin{equation*}
\mathbf{f}(y) \geq \mathbf{f}(x) + \langle y-x, \nabla \mathbf{f}(x) \rangle+ \frac{\alpha}{2} \|y-x\|^2\quad \forall~x,y \in \mathbb{R}^p.
\end{equation*}
\end{defn}

\begin{defn}We  say that a function $\mathbf{f}: \mathbb{R}^p \rightarrow \mathbb{R}$ is called $L$-smooth for given   $L >0$ if $f$ has Lipschitz continuous gradient with constant $L$, i.e., 
\begin{equation*}
\|\nabla \mathbf{f}(x) - \nabla \mathbf{f}(y)\| \leq L \|x-y\|\quad \forall~x,y \in\mathbb{R}^p.
\end{equation*}
\end{defn}

\begin{equation}\label{NEAR DGD}
{\bf {\bf x}}_{k+1} = \big(W^{t(k)}\otimes I_p\big)\big({\bf x}_k - \mu \nabla F({\bf x}_k)\big)\quad \forall~ k \geq0,%\in \mathbb{N},
\end{equation}

where ${\bf x}_k= (x_{1,k}^{\top}, x_{2,k}^{\top}, \cdots, x_{n,k}^{\top})^{\top}$ and $\mu >0$. Here  $\nabla F (\mathbf{x}_k)\in \mathbb{R}^{np}$ denotes
\begin{equation*}
\nabla F({\bf x}_k)=\left(
\nabla f_1(x_{1,k})^{\top},\cdots
, \nabla f_n(x_{n,k})^{\top}
\right)^{\top}
\end{equation*}

and the exponent $t(k) \in \mathbb{N}$ indicates the number of consensus step. 


 To state convergence results, we introduce the averaging of any $np$-dimensional vector $\bold x$:
\begin{align}
\bar{\bf x}=\frac{1}{n}\big(1_n1^{\top}_n\!\!\otimes I_p\big){\bold x}
\end{align}

where $1_n$ is a column vector in $\mathbb{R}^n$ whose entries are all $1$. In particular, we  have
\begin{align}\label{11t}
\bar{{\bf x}}_k=\frac{1}{n}\big(1_n1^{\top}_n\!\!\otimes I_p\big){\bf x}_k~~\mbox{  and  }~~ 
\overline{\nabla  F} (\mathbf{x}_k)=\frac{1}{n}\big(1_n1^{\top}_n\!\!\otimes I_p\big)\nabla F (\mathbf{x}_k).
\end{align}

We note that
$$
\bar{{\bf x}}_k=1_n\otimes\left(\frac{1}{n}\sum_{i=1}^nx_{i,k}\right)=1_n\otimes \bar x_k= (\bar x_{k}^{\top},\bar x_{k}^{\top},\cdots,\bar x_{k}^{\top})^{\top}.
$$

Using these notation for averaged quantities, we derive the following averaged version of (\ref{NEAR DGD}) which plays an important role as a useful intermediate step in the convergence analysis:
\begin{equation}\label{average}
\bar{{\bf x}}_{k+1} = \bar{{\bf x}}_k - \mu \overline{\nabla F}({\bf x}_k),
\end{equation}

where we used the property that $1_n^\top W = 1_n^\top$ coming from the column-stochasticity of the consensus matrix $W$.

