\begin{lem}\label{lem-2-1} Assume that $f: \mathbb{R}^n \rightarrow \mathbb{R}$ is $\alpha$-strongly convex and $L$-smooth. Then, for any $x,y \in \mathbb{R}^n$ we have
\begin{equation*}
\langle \nabla f(x) - \nabla f(y), x-y \rangle \geq \frac{L\alpha}{L+\alpha}\|x-y\|^2 + \frac{1}{\alpha +L} \|\nabla f(x) - \nabla f(y)\|^2.
\end{equation*}
\end{lem}

\begin{prop}\label{prop-2-2} 
Let  $\{X_k\}_{k\geq0}$ and $\{Y_k\}_{k\geq0}$ be sequences of non-negative vectors in $\mathbb{R}^2$ and $\{M_k\}_{k\geq0}$ be a sequence of $2\times 2$ matrices. Assume that $\{X_k\}_{k\geq0}$, $\{Y_k\}_{k\geq0}$ and $\{M_k\}_{k\geq0}$ satisfy the following iterative relation:
	\begin{equation*}
	X_{k+1} \leq M_k X_k + Y_k.
	\end{equation*}
	Suppose further that $\{Y_k\}_{k \geq0}$ is a sequence of non-negative vectors such that $\sum_{k=0}^{\infty}\big\| Y_k \big\|< \infty$, and $\{M_k\}_{k\geq0}$ takes the following form:
	 \begin{equation*}
	 M_k = \begin{pmatrix} 1 & r \\ \alpha_k & \alpha_k \end{pmatrix}
	 \end{equation*}
	 for some fixed $r>0$ and a sequence of non-negative real numbers $\{\alpha_k\}_{k\geq0}$ satisfying  $\sum_{k=0}^{\infty} \alpha_k <\infty$. 
 Then, we have
 \begin{enumerate}
 	 	\item The matrix $M_b M_{b-1}\dots M_a$   is uniformly bounded for $0 \leq a < b< \infty$.
 	\item  $\{X_{k}\}_{k\geq0}$ is uniformly bounded.
 	\end{enumerate}
\end{prop}

\begin{proof}
(1) We take $c = \max\{r,1\}$ and define a weighted norm $\|\cdot\|_{c}$ in $\mathbb{R}^2$ by
\begin{equation*}
\|(x,y)^\top\|_c = |x| + c|y| \quad \textcolor{black}{\mbox{for }x,y\in\mathbb{R}}.
\end{equation*}
For a matrix $M \in \mathbb{R}^{2\times 2}$, we define the  operator norm by
\begin{equation*}
\|M\|_{\mathcal{L}} =\sup_{v \in \mathbb{R}^2 \setminus \{0\}} \frac{\|Mv\|_{c}}{\|v\|_{c}}.
\end{equation*}
We claim that
\begin{equation*}\label{eq-2-3}
\|M_k\|_{\mathcal{L}} \leq 1+ c\alpha_k.
\end{equation*}
To show this, we take an arbitrary $v = (x,y)^\top \in \mathbb{R}^2$ and compute
\begin{equation*}
M_kv=\begin{pmatrix} 1 & r \\ \alpha_k &\alpha_k \end{pmatrix} \begin{pmatrix} x \\ y \end{pmatrix} = \begin{pmatrix} x + ry \\ \alpha_k x + \alpha_k y \end{pmatrix},
\end{equation*}
which has the weighted $L^1$ norm as
\begin{equation*}
\|M_kv\|_{c} = |x+ry| + c |\alpha_k x + \alpha_k y| \leq (1+c\alpha_k)|x| + (r+c \alpha_k )|y|.
\end{equation*}
Since $c = \max\{r,1\}$ we have
\begin{equation*}
r+c \alpha_k \leq c (1+c\alpha_k)
\end{equation*}
so that
\begin{equation*}
\begin{split}
\|M_kv\|_c&\leq(1+c\alpha_k) |x| + (r+c \alpha_k ) |y|
\\
&\leq (1+c\alpha_k) (|x|+c|y|) = (1+c\alpha_k) \|v\|_c.
\end{split}
\end{equation*}
This proves the claim. Using \eqref{eq-2-3}, for any $1\leq a<b<\infty$ we  obtain
\begin{equation*}
\begin{split}
\Big\| M_b M_{b-1}\dots M_a \Big\|_{\mathcal{L}}& \leq \prod_{k=a}^b \|M_k \|_{\mathcal{L}}
\\
& \leq \prod_{k=a}^b (1+c\alpha_k)
\\
& \leq \prod_{k=a}^b e^{c\alpha_k} = \exp \Big(c\sum_{k=a}^b \alpha_k\Big).
\end{split}
\end{equation*}
Combining this with the assumption that $\sum_{k=0}^{\infty} \alpha_k < \infty$, we conclude that $\Big\| M_b M_{b-1}\dots M_a \Big\|_{\mathcal{L}} $ is uniformly bounded for $0\leq a<b <\infty$.

\noindent (2) By induction, the iteration implies that
\begin{equation}\label{eq-2-10}
X_{k+1} \leq \Big( M_k M_{k-1}\dots M_0\Big)X_0 + \sum_{j=0}^{k-1} \Big( M_k M_{k-1}\dots M_{j+1}\Big) Y_j + Y_k.
\end{equation}
This gives the desired uniform boundedness of $X_k$ since $M_b M_{b-1}\dots M_a$ is uniformly bounded and $\sum_{j=0}^{\infty} \big\|Y_j \big\|< \infty$. 
\end{proof}

\begin{lem}\label{newlemma}\cite{QL}
Assume that the consensus matrix $W$ satisfies the following:
\begin{itemize}
\item $W$ is a doubly-stochastic $n\times n$ matrix.
\item The directed graph associated to $W$ is strongly connected, and has a self-loop at every vertex.
\end{itemize}
Then the following assertions hold:
\begin{enumerate}
\item The graph associated to $W^\top W$ is connected and aperiodic. (Since $W^\top W$ is symmetric, we may either interpret its associated graph as a strongly connected directed graph, or a connected undirected graph, depending on preference.)
\item The largest eigenvalue of $W^\top W$ is $1$, and it is simple.
\item The spectral norm $\beta$ of $W-\frac{1}{n}1_n1_n^\top$ satisfies $\beta\in[0,1)$.
\end{enumerate}
\end{lem}

\begin{proof}
(1) The assumption that the graph associated to $W$ has a self-loop at every vertex, is equivalent to $w_{ii}>0$ for all $1\leq i\leq n$. Let $w_0:=\frac{1}{2}\min\limits_{1\leq i\leq n}w_{ii}>0$ and $\widetilde W:=W-w_0 I_n$. Then all entries of $\widetilde W$ are nonnegative, and the directed graph associated to $\widetilde W$ is precisely the same as that of $W$. Note that
\[
W^\top W=(\widetilde W+w_0I_n)^\top(\widetilde W+w_0I_n)\geq w_0 \widetilde W,
\]
with the inequality being in entrywise sense. Hence the graph associated to $W^\top W$ contains that associated to $\widetilde W$ (or $W$) as its subgraph, which is indeed strongly connected and aperiodc.

(2) Since $W^\top W$ is symmetric positive semidefinite, we can arrange its eigenvalues as $\lambda_1\geq \lambda_2\geq\dots\geq\lambda_n\geq0$. The Perron-Frobenius theorem combined with (1) yields $1=\lambda_1>\lambda_2$.

(3) Since $W^\top W$ is symmetric, it can be diagonalized by an orthogonal matrix, i.e.,
\[
W^\top W=Q \operatorname{diag}(\lambda_1,\dots,\lambda_n)Q^\top,\quad Q:=[u_1|\dots|u_n],
\]
with $u_i$ being an eigenvector associated to $\lambda_i$, $i=1,\dots,n$. Note that $\lambda_1=1$ and $u_1=\frac{1}{\sqrt{n}}1_n$, because $W$ is doubly-stochastic. Hence
\[
W^\top W=\sum_{i=1}^n \lambda_i u_iu_i^\top=\frac{1}{n}1_n1_n^\top+\sum_{i=2}^n \lambda_i u_iu_i^\top,
\]
which yields
\begin{align*}
\left\|W-\frac{1}{n}1_n1_n^\top\right\|&=\sqrt{\mbox{the largest eigenvalue of }(W-\frac{1}{n}1_n1_n^\top)^\top(W-\frac{1}{n}1_n1_n^\top)}\\
&=\sqrt{\mbox{the largest eigenvalue of }W^\top W-\frac{1}{n}1_n1_n^\top}=\sqrt{\lambda_2}<1,
\end{align*}
where the second equality follows using that $1_n 1_n^\top W = 1_n 1_n^\top$ and $W^\top 1_n 1_n^\top  = 1_n 1_n^\top$ since $W$ is doubly-stochastic. The proof is finished.
\end{proof}

\begin{proof}[Proof of Theorem \ref{Main1}]We define
\begin{equation}\label{eq-3-10}
A_k:= \|\bar{\bf x}_k-{\bf x}_*\| = \sqrt{n} \|\bar{x}_k - x_*\|,\quad B_k:=\|{\bf x}_k-\bar{\bf x}_k\|
\end{equation}
and proceed to obtain a recursive estimate for $A_k$ and $B_k$. We first estimate $B_{k+1}$ in terms of $A_k$ and $B_k$. For this, we use the algorithm \eqref{NEAR DGD} along with \eqref{average} and  \eqref{11t} to find
\begin{equation}\label{eq-3-30}
\begin{split}
&\|\bar{{\bf x}}_{k+1} - {\bf x}_{k+1}\|\cr
 & = \|(\bar{{\bf x}}_k - \mu \overline{\nabla F}({\bf x}_k)) - (W^{t(k)}\otimes I_p) ({\bf x}_k - \mu \nabla F({\bf x}_k))\|
\\
& = \left\| \left[\left( \frac{1}{n} 1_n 1_n^\top  - W^{t(k)}\right)\otimes I_p\right] ({\bf x}_k -\mu \nabla F({\bf x}_k) \right\|
\\
&\leq \left\| \left[\left( \frac{1}{n} 1_n 1_n^\top  - W^{t(k)}\right)\otimes I_p\right] {\bf x}_k \right\| + \mu \left\| \left[\left( \frac{1}{n} 1_n 1_n^\top  - W^{t(k)}\right)\otimes I_p\right] \nabla F({\bf x}_k)\right\|.
\end{split}
\end{equation}
Here we can estimate the right hand side using 
\begin{equation}\label{eq-3-31}
\left\{\left( \frac{1}{n} 1_n 1_n^\top  - W^{t(k)}\right)\otimes I_p\right\} \bar{\bf x}_k=0 
	\quad \textrm{and}\quad
	\Big\| \frac{1}{n} 1_n 1_n^\top  - W^{t(k)}\Big\|_2\leq \beta^{t(k)},
	\end{equation}
where the second inequality came from Lemma \ref{newlemma} and the relation
\[
 W^{t(k)}-\frac{1}{n} 1_n 1_n^\top  = \left(W-\frac{1}{n} 1_n 1_n^\top \right)^{t(k)}.
\]
Using \eqref{eq-3-31} in \eqref{eq-3-30} and  the triangle inequality,  we  achieve
\begin{align}\label{consensus estimate}
\begin{split}
\|\bar{{\bf x}}_{k+1} - {\bf x}_{k+1}\|&\leq {}\beta^{t(k)} \|{\bf x}_k - \bar{\bf x}_k\| + {}\mu \beta^{t(k)} \|\nabla F({\bf x}_k)\|\cr
 &\leq {}\beta^{t(k)} \|{\bf x}_k - \bar{\bf x}_k\| + {}\mu \beta^{t(k)} 
 \left\{\|\nabla F({\bf x}_k)-\nabla F(\bar{\bf x}_k)\|\right.\cr
 &\quad\left.+\|\nabla F(\bar{\bf x}_k)-\nabla F({\bf x}_*)\|
 +\|\nabla F({\bf x}_*)\|
 \right\}.\cr
 \end{split}
 \end{align}
We note that the $L_j$-smoothness of $f_j$ yields that for $x, y \in \mathbb{R}^{np}$ we have
\begin{equation*}
\begin{split}
\| \nabla F (x) - \nabla F(y) \| & = \Bigg( \sum_{j=1}^n \|\nabla f_j (x^j) - \nabla f_j (y^j) \|^2 \Bigg)^{1/2} 
\\
&\leq \Bigg(\sum_{j=1}^n \textcolor{black}{L_j^2 \|x^j -y^j\|^2} \Bigg)^{1/2} 
\\
& \leq L \|x-y\|,
\end{split}
\end{equation*}
where we denoted $x= ((x^1)^\top, \cdots, (x^n)^\top)^\top$ and $y= ((y^1)^\top, \cdots, (y^n)^\top)^\top$. Using this in \eqref{consensus estimate} we obtain
 \begin{equation}\label{eq-3-32}
 \begin{split}
 \|\bar{{\bf x}}_{k+1} - {\bf x}_{k+1}\| &\leq {}(1+\mu L)\beta^{t(k)} 
 \|{\bf x}_k-\bar{\bf x}_k \|
 +{}(\mu L)\beta^{t(k)}\|\bar{\bf x}_k-{\bf x}_*\|
 +{}\mu\beta^{t(k)}D
 \\
 & ={}(1+\mu L)\beta^{t(k)} 
 \|{\bf x}_k-\bar{\bf x}_k \|
 + {}(\mu \sqrt{n} L)\beta^{t(k)}\|\bar{x}_k-{x}_*\|
 +{}\mu\beta^{t(k)}D,
\end{split}
\end{equation}
where $D:=\|\nabla F({\bf x}_*)\|$. This gives
\begin{align}\label{estimate A}
B_{k+1} \leq  {}(\mu L)\beta^{t(k)}A_k+{}(1+\mu L)\beta^{t(k)}B_k+{}\mu\beta^{t(k)} D. 
\end{align}
Next we estimate the error $A_{k+1}$ between the average and the optimizer $x_*$ in terms of $A_k$ and $B_k$. Using \eqref{average} and the triangle inequality, we find
\begin{align}\label{main comp}
\begin{split}
\|\bar{{ x}}_{k+1} - { x}_*\| 
 &= \bigg\|\bar{{x}}_k - {x}_* - \frac{\mu}{n} \sum_{j=1}^n \nabla f_j (x_{j,k})\bigg\|\\
& = \bigg\|\bar{{ x}}_k - {x}_* - \frac{\mu}{n} \sum_{j=1}^n \nabla f_j (\bar{x}_k) + \mu \bigg( \frac{1}{n} \sum_{j=1}^n \nabla f_j (\bar{x}_k)- \frac{1}{n} \sum_{j=1}^n \nabla f_j (x_{j,k})\bigg)\bigg\|\cr
