\end{equation*}
\end{defn}

\begin{defn}We  say that a function $\mathbf{f}: \mathbb{R}^p \rightarrow \mathbb{R}$ is called $L$-smooth for given   $L >0$ if $f$ has Lipschitz continuous gradient with constant $L$, i.e., 
\begin{equation*}
\|\nabla \mathbf{f}(x) - \nabla \mathbf{f}(y)\| \leq L \|x-y\|\quad \forall~x,y \in\mathbb{R}^p.
\end{equation*}
\end{defn}

