\begin{thm}\label{Main1} Suppose that the cost function $f$ is convex and each local cost $f_i$ is $L_i$-smooth 
for some $L_i>0$. Assume that $\mu \in (0,2/L]$ with $L = \max_{1 \leq i \leq n} L_i$ and the sequence $\{t(k)\}_{k \in \mathbb{N}\cup\{0\}}$ satisfies $\sum_{k=0}^\infty \beta^{t(k)} <\infty$. Then, for any minimizer $x_*\in X^*$ , we have%there exists a constant $R>0$ such that
\begin{equation}\label{eq-1-1}
\|{\bar{\bf x}}_k -{\bf x}_*\|=O(1)\quad \textrm{and}\quad\|\bar{\bold x}_{k+1} -\bold x_{k+1}\| = O(\beta^{t(k)}),\quad k\to\infty,%\forall~k \in \mathbb{N},
\end{equation}
where %$Q = \Big[ (1+2\mu L) R + \mu D \Big]$ and 
$\bold x_*:=1_n\otimes x_* =(x_*^{\top},x_*^{\top},\cdots,x_*^{\top})^{\top}$. 	
%	 Then, there exists $\bar\mu$ such that if  $\mu<\bar\mu$, then the discrepancy from the optimal solution $\|{\bf x}_k-{\bf x}_*\|$ is bounded uniformly in $k$.
\end{thm}

\begin{proof}[Proof of Theorem \ref{Main1}]We define
\begin{equation}\label{eq-3-10}
A_k:= \|\bar{\bf x}_k-{\bf x}_*\| = \sqrt{n} \|\bar{x}_k - x_*\|,\quad B_k:=\|{\bf x}_k-\bar{\bf x}_k\|
\end{equation}
and proceed to obtain a recursive estimate for $A_k$ and $B_k$. We first estimate $B_{k+1}$ in terms of $A_k$ and $B_k$. For this, we use the algorithm \eqref{NEAR DGD} along with \eqref{average} and  \eqref{11t} to find
\begin{equation}\label{eq-3-30}
\begin{split}
&\|\bar{{\bf x}}_{k+1} - {\bf x}_{k+1}\|\cr
 & = \|(\bar{{\bf x}}_k - \mu \overline{\nabla F}({\bf x}_k)) - (W^{t(k)}\otimes I_p) ({\bf x}_k - \mu \nabla F({\bf x}_k))\|
\\
& = \left\| \left[\left( \frac{1}{n} 1_n 1_n^\top  - W^{t(k)}\right)\otimes I_p\right] ({\bf x}_k -\mu \nabla F({\bf x}_k) \right\|
\\
&\leq \left\| \left[\left( \frac{1}{n} 1_n 1_n^\top  - W^{t(k)}\right)\otimes I_p\right] {\bf x}_k \right\| + \mu \left\| \left[\left( \frac{1}{n} 1_n 1_n^\top  - W^{t(k)}\right)\otimes I_p\right] \nabla F({\bf x}_k)\right\|.
\end{split}
\end{equation}
Here we can estimate the right hand side using 
\begin{equation}\label{eq-3-31}
\left\{\left( \frac{1}{n} 1_n 1_n^\top  - W^{t(k)}\right)\otimes I_p\right\} \bar{\bf x}_k=0 
	\quad \textrm{and}\quad
	\Big\| \frac{1}{n} 1_n 1_n^\top  - W^{t(k)}\Big\|_2\leq \beta^{t(k)},
	\end{equation}
where the second inequality came from Lemma \ref{newlemma} and the relation
\[
 W^{t(k)}-\frac{1}{n} 1_n 1_n^\top  = \left(W-\frac{1}{n} 1_n 1_n^\top \right)^{t(k)}.
\]
Using \eqref{eq-3-31} in \eqref{eq-3-30} and  the triangle inequality,  we  achieve
\begin{align}\label{consensus estimate}
\begin{split}
\|\bar{{\bf x}}_{k+1} - {\bf x}_{k+1}\|&\leq {}\beta^{t(k)} \|{\bf x}_k - \bar{\bf x}_k\| + {}\mu \beta^{t(k)} \|\nabla F({\bf x}_k)\|\cr
 &\leq {}\beta^{t(k)} \|{\bf x}_k - \bar{\bf x}_k\| + {}\mu \beta^{t(k)} 
 \left\{\|\nabla F({\bf x}_k)-\nabla F(\bar{\bf x}_k)\|\right.\cr
 &\quad\left.+\|\nabla F(\bar{\bf x}_k)-\nabla F({\bf x}_*)\|
 +\|\nabla F({\bf x}_*)\|
 \right\}.\cr
 \end{split}
 \end{align}
We note that the $L_j$-smoothness of $f_j$ yields that for $x, y \in \mathbb{R}^{np}$ we have
\begin{equation*}
\begin{split}
\| \nabla F (x) - \nabla F(y) \| & = \Bigg( \sum_{j=1}^n \|\nabla f_j (x^j) - \nabla f_j (y^j) \|^2 \Bigg)^{1/2} 
\\
&\leq \Bigg(\sum_{j=1}^n \textcolor{black}{L_j^2 \|x^j -y^j\|^2} \Bigg)^{1/2} 
\\
& \leq L \|x-y\|,
\end{split}
\end{equation*}
where we denoted $x= ((x^1)^\top, \cdots, (x^n)^\top)^\top$ and $y= ((y^1)^\top, \cdots, (y^n)^\top)^\top$. Using this in \eqref{consensus estimate} we obtain
 \begin{equation}\label{eq-3-32}
 \begin{split}
 \|\bar{{\bf x}}_{k+1} - {\bf x}_{k+1}\| &\leq {}(1+\mu L)\beta^{t(k)} 
 \|{\bf x}_k-\bar{\bf x}_k \|
 +{}(\mu L)\beta^{t(k)}\|\bar{\bf x}_k-{\bf x}_*\|
 +{}\mu\beta^{t(k)}D
 \\
 & ={}(1+\mu L)\beta^{t(k)} 
 \|{\bf x}_k-\bar{\bf x}_k \|
 + {}(\mu \sqrt{n} L)\beta^{t(k)}\|\bar{x}_k-{x}_*\|
 +{}\mu\beta^{t(k)}D,
\end{split}
\end{equation}
where $D:=\|\nabla F({\bf x}_*)\|$. This gives
\begin{align}\label{estimate A}
B_{k+1} \leq  {}(\mu L)\beta^{t(k)}A_k+{}(1+\mu L)\beta^{t(k)}B_k+{}\mu\beta^{t(k)} D. 
\end{align}
Next we estimate the error $A_{k+1}$ between the average and the optimizer $x_*$ in terms of $A_k$ and $B_k$. Using \eqref{average} and the triangle inequality, we find
\begin{align}\label{main comp}
\begin{split}
\|\bar{{ x}}_{k+1} - { x}_*\| 
 &= \bigg\|\bar{{x}}_k - {x}_* - \frac{\mu}{n} \sum_{j=1}^n \nabla f_j (x_{j,k})\bigg\|\\
& = \bigg\|\bar{{ x}}_k - {x}_* - \frac{\mu}{n} \sum_{j=1}^n \nabla f_j (\bar{x}_k) + \mu \bigg( \frac{1}{n} \sum_{j=1}^n \nabla f_j (\bar{x}_k)- \frac{1}{n} \sum_{j=1}^n \nabla f_j (x_{j,k})\bigg)\bigg\|\cr
&\leq \|\bar{{  x}}_k - {  x}_* - \mu \nabla f (\bar{{ x}}_k) \|+ \mu \bigg\|\frac{1}{n} \sum_{j=1}^n \nabla f_j (\bar{x}_k)- \frac{1}{n} \sum_{j=1}^n \nabla f_j (x_{j,k})\bigg\|.
\end{split}
\end{align}
We make use of $\nabla f(x_*)=0$ to compute
\begin{equation}\label{eq-3-1}
\begin{split}
&\|\bar{{x}}_k- {x}_*-\mu{\nabla f}(\bar{{x}}_k)\|^2\\
&\quad= \|\bar{{ x}}_k-{ x}_*\|^2
-2\mu\langle  \bar{{x}}_k-{x}_*,\nabla f(\bar{{ x}}_k)\rangle
+\mu^2\|\nabla f(\bar{{ x}}_k)\|^2\\
&\quad=\|\bar{{x}}_k-{x}_*\|^2
-2\mu\langle  \bar{{x}}_k-{x}_*, {\nabla f}(\bar{{x}}_k)
- {\nabla f}({{x}}_*)\rangle
+\mu^2\|{\nabla f}(\bar{{x}}_k)-{\nabla f}({x}_*)\|^2.
\end{split}
\end{equation}
From Lemma \ref{lem-2-1}, we find
\begin{equation}\label{eq-3-2}
\langle \bar{x}_k -{x}_*,  {\nabla f}(\bar{x}_k)- {\nabla f}({ x}_*)\rangle \geq\frac{1}{L}\| \textcolor{black}{{\nabla f}(\bar{ x}_k)}-{\nabla f}({x}_*)\|^2,
\end{equation}
and apply it to \eqref{eq-3-1} to obtain
\begin{align*}
\begin{split}
& \|\bar{{x}}_k-{x}_*-\mu{\nabla f}(\bar{{x}}_k)\|^2\\
&\quad\leq\|\bar{{x}}_k-{x}_*\|^2+\mu\left(\mu-\frac{2}{L}\right)\|{\nabla f}(\bar{{x}}_k)-{\nabla f}({{x}}_*)\|^2\cr
&\quad\leq \|\bar{{x}}_k-{x}_*\|^2
\end{split}
\end{align*}
for $\mu \in (0, 2/L]$.
This gives us the estimate
\begin{align}\label{eq-3-6}
&\|\bar{{x}}_k-{x}_*-\mu {\nabla f}(\bar{{ x}}_k)\|
\leq \|\bar{{x}}_k-{x}_*\|.
\end{align}
On the other hand, we use the $L_j$-smoothness of $f_j$ and the triangle inequality to deduce
\begin{align}\label{insert1}
\begin{split} 
 \bigg\|\frac{1}{n} \sum_{j=1}^n \nabla f_j (\bar{x}_k)- \frac{1}{n} \sum_{j=1}^n \nabla f_j (x_{j,k})\bigg\| & \leq \frac{1}{n} \sum_{j=1}^n L_j \|\bar{x}_k - x_{j,k}\|
 \\
&\leq \frac{L}{\sqrt{n}} \|\bar{{\bf x}}_k - {\bf x}_k\|.
\end{split}
\end{align}
Combining \eqref{main comp},  \eqref{eq-3-6} and \eqref{insert1}, we get
\begin{align}\label{line for A}
\begin{split}
\|\bar{{x}}_{k+1}- {{x}}_*\|
\leq \|\bar{{x}}_k- {{x}}_*\|+ \frac{\mu L}{\sqrt{n}}\|{\bf x}_k-\bar{{\bf x}}_k\|.
\end{split}
\end{align}
From \eqref{estimate A} and \eqref{line for A}, we get the following iterative relation:
\begin{equation}\label{eq-3-50}
\left(\begin{array}{c} A_{k+1}\cr B_{k+1}\end{array}\right) \leq
\left(\begin{array}{cc} 1 &  \mu L\cr {}(\mu L) \beta^{t(k)}& {} (1+\mu L)\beta^{t(k)}\end{array}\right)
\left(\begin{array}{c} A_{k}\cr B_{k}\end{array}\right)
+
{}\beta^{t(k)}\left(\begin{array}{c} 0\cr \mu D\end{array}\right),
\end{equation}
\textcolor{black}{
which clearly implies
\begin{align*}
\left(\begin{array}{c} A_{k+1}\cr B_{k+1}\end{array}\right) \leq
\left(\begin{array}{cc} 1 &  \mu L\cr {}(1+\mu L) \beta^{t(k)}& {} (1+\mu L)\beta^{t(k)}\end{array}\right)
\left(\begin{array}{c} A_{k}\cr B_{k}\end{array}\right)
+
{}\beta^{t(k)}\left(\begin{array}{c} 0\cr \mu D\end{array}\right). 
\end{align*}
}
Now we apply Proposition \ref{prop-2-2} to conclude that there exists $R>0$ such that
\begin{equation*}
\|\bar{\bf x}_k -\bold x_*\| \leq R \quad \textrm{and}\quad \|\bar{\bold x}_k -\bold x_k \| \leq R
\end{equation*}
for all $k \in \mathbb{N}$. By applying this bound to \eqref{estimate A}, we obtain
\begin{equation*}
\|\bar{\bold x}_{k+1} -\bold x_{k+1}\| \leq {}\beta^{t(k)} \Big[ (1+2\mu L) R + \mu D \Big].
\end{equation*}
This completes the proof.
\end{proof}

