\begin{prop}\label{prop-2-2} 
Let  $\{X_k\}_{k\geq0}$ and $\{Y_k\}_{k\geq0}$ be sequences of non-negative vectors in $\mathbb{R}^2$ and $\{M_k\}_{k\geq0}$ be a sequence of $2\times 2$ matrices. Assume that $\{X_k\}_{k\geq0}$, $\{Y_k\}_{k\geq0}$ and $\{M_k\}_{k\geq0}$ satisfy the following iterative relation:
	\begin{equation*}
	X_{k+1} \leq M_k X_k + Y_k.
	\end{equation*}
	Suppose further that $\{Y_k\}_{k \geq0}$ is a sequence of non-negative vectors such that $\sum_{k=0}^{\infty}\big\| Y_k \big\|< \infty$, and $\{M_k\}_{k\geq0}$ takes the following form:
	 \begin{equation*}
	 M_k = \begin{pmatrix} 1 & r \\ \alpha_k & \alpha_k \end{pmatrix}
	 \end{equation*}
	 for some fixed $r>0$ and a sequence of non-negative real numbers $\{\alpha_k\}_{k\geq0}$ satisfying  $\sum_{k=0}^{\infty} \alpha_k <\infty$. 
 Then, we have
 \begin{enumerate}
 	 	\item The matrix $M_b M_{b-1}\dots M_a$   is uniformly bounded for $0 \leq a < b< \infty$.
 	\item  $\{X_{k}\}_{k\geq0}$ is uniformly bounded.
 	\end{enumerate}
\end{prop}

Let  $\{X_k\}_{k\geq0}$ and $\{Y_k\}_{k\geq0}$ be sequences of non-negative vectors in $\mathbb{R}^2$ and $\{M_k\}_{k\geq0}$ be a sequence of $2\times 2$ matrices. Assume that $\{X_k\}_{k\geq0}$, $\{Y_k\}_{k\geq0}$ and $\{M_k\}_{k\geq0}$ satisfy the following iterative relation:
	\begin{equation*}
	X_{k+1} \leq M_k X_k + Y_k.
	\end{equation*}
	Suppose further that $\{Y_k\}_{k \geq0}$ is a sequence of non-negative vectors such that $\sum_{k=0}^{\infty}\big\| Y_k \big\|< \infty$, and $\{M_k\}_{k\geq0}$ takes the following form:
	 \begin{equation*}
	 M_k = \begin{pmatrix} 1 & r \\ \alpha_k & \alpha_k \end{pmatrix}
	 \end{equation*}
	 for some fixed $r>0$ and a sequence of non-negative real numbers $\{\alpha_k\}_{k\geq0}$ satisfying  $\sum_{k=0}^{\infty} \alpha_k <\infty$.

\begin{proof}
(1) We take $c = \max\{r,1\}$ and define a weighted norm $\|\cdot\|_{c}$ in $\mathbb{R}^2$ by
\begin{equation*}
\|(x,y)^\top\|_c = |x| + c|y| \quad \textcolor{black}{\mbox{for }x,y\in\mathbb{R}}.
\end{equation*}
For a matrix $M \in \mathbb{R}^{2\times 2}$, we define the  operator norm by
\begin{equation*}
\|M\|_{\mathcal{L}} =\sup_{v \in \mathbb{R}^2 \setminus \{0\}} \frac{\|Mv\|_{c}}{\|v\|_{c}}.
\end{equation*}
We claim that
\begin{equation*}\label{eq-2-3}
\|M_k\|_{\mathcal{L}} \leq 1+ c\alpha_k.
\end{equation*}
To show this, we take an arbitrary $v = (x,y)^\top \in \mathbb{R}^2$ and compute
\begin{equation*}
M_kv=\begin{pmatrix} 1 & r \\ \alpha_k &\alpha_k \end{pmatrix} \begin{pmatrix} x \\ y \end{pmatrix} = \begin{pmatrix} x + ry \\ \alpha_k x + \alpha_k y \end{pmatrix},
\end{equation*}
which has the weighted $L^1$ norm as
\begin{equation*}
\|M_kv\|_{c} = |x+ry| + c |\alpha_k x + \alpha_k y| \leq (1+c\alpha_k)|x| + (r+c \alpha_k )|y|.
\end{equation*}
Since $c = \max\{r,1\}$ we have
\begin{equation*}
r+c \alpha_k \leq c (1+c\alpha_k)
\end{equation*}
so that
\begin{equation*}
\begin{split}
\|M_kv\|_c&\leq(1+c\alpha_k) |x| + (r+c \alpha_k ) |y|
\\
&\leq (1+c\alpha_k) (|x|+c|y|) = (1+c\alpha_k) \|v\|_c.
\end{split}
\end{equation*}
This proves the claim. Using \eqref{eq-2-3}, for any $1\leq a<b<\infty$ we  obtain
\begin{equation*}
\begin{split}
\Big\| M_b M_{b-1}\dots M_a \Big\|_{\mathcal{L}}& \leq \prod_{k=a}^b \|M_k \|_{\mathcal{L}}
\\
& \leq \prod_{k=a}^b (1+c\alpha_k)
\\
& \leq \prod_{k=a}^b e^{c\alpha_k} = \exp \Big(c\sum_{k=a}^b \alpha_k\Big).
\end{split}
\end{equation*}
Combining this with the assumption that $\sum_{k=0}^{\infty} \alpha_k < \infty$, we conclude that $\Big\| M_b M_{b-1}\dots M_a \Big\|_{\mathcal{L}} $ is uniformly bounded for $0\leq a<b <\infty$.

\noindent (2) By induction, the iteration implies that
\begin{equation}\label{eq-2-10}
X_{k+1} \leq \Big( M_k M_{k-1}\dots M_0\Big)X_0 + \sum_{j=0}^{k-1} \Big( M_k M_{k-1}\dots M_{j+1}\Big) Y_j + Y_k.
\end{equation}
This gives the desired uniform boundedness of $X_k$ since $M_b M_{b-1}\dots M_a$ is uniformly bounded and $\sum_{j=0}^{\infty} \big\|Y_j \big\|< \infty$. 
\end{proof}

