\begin{lem}\label{newlemma}\cite{QL}
Assume that the consensus matrix $W$ satisfies the following:
\begin{itemize}
\item $W$ is a doubly-stochastic $n\times n$ matrix.
\item The directed graph associated to $W$ is strongly connected, and has a self-loop at every vertex.
\end{itemize}
Then the following assertions hold:
\begin{enumerate}
\item The graph associated to $W^\top W$ is connected and aperiodic. (Since $W^\top W$ is symmetric, we may either interpret its associated graph as a strongly connected directed graph, or a connected undirected graph, depending on preference.)
\item The largest eigenvalue of $W^\top W$ is $1$, and it is simple.
\item The spectral norm $\beta$ of $W-\frac{1}{n}1_n1_n^\top$ satisfies $\beta\in[0,1)$.
\end{enumerate}
\end{lem}

\begin{lem}\label{lem-2-1} Assume that $f: \mathbb{R}^n \rightarrow \mathbb{R}$ is $\alpha$-strongly convex and $L$-smooth. Then, for any $x,y \in \mathbb{R}^n$ we have
\begin{equation*}
\langle \nabla f(x) - \nabla f(y), x-y \rangle \geq \frac{L\alpha}{L+\alpha}\|x-y\|^2 + \frac{1}{\alpha +L} \|\nabla f(x) - \nabla f(y)\|^2.
\end{equation*}
\end{lem}
